function educationalOfferStudentIds(payments:SalesPaymentRow[],offers:SalesOfferRow[]) {
  const offerLevels=new Map<number,number>();
  for(const offer of offers){try{offerLevels.set(offer.id,Math.max(0,Number((JSON.parse(offer.customData||"{}") as Record<string,unknown>).levels)||0))}catch{}}
  const result=new Set<number>();
  for(const payment of payments){let details:Record<string,unknown>={};try{details=JSON.parse(payment.customData||"{}")}catch{}const levels=Math.max(0,Number(details.levels??offerLevels.get(Number(details.offerId))??0)-Number(details.refundedLevels||0));if(payment.status!=="Voided"&&!details.voided&&details.isMainPayment&&levels>0)result.add(payment.studentId)}
  return result;
}

